const results = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const binary = items[i].binary && items[i].binary.data;
  if (!binary) {
    throw new Error('No binary audio data found on this item.');
  }
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  results.push({
    json: {
      audio_base64: buffer.toString('base64'),
      chat_id: $('WhatsApp Normalizer').item.json.message.chat.id
    }
  });
}
return results;

const chatId = $('WhatsApp Normalizer').first().json.message.chat.id;
const candidate = $json.candidates && $json.candidates[0];
const part = candidate && candidate.content && candidate.content.parts && candidate.content.parts[0];
const transcript = (part && part.text) ? part.text.trim() : '';

const today = new Date();
const todayStr = today.toISOString().slice(0, 10);
const dayName = today.toLocaleDateString('ar-EG', { weekday: 'long' });

const combinedText = `(ملحوظة للنظام: تاريخ النهاردة الحقيقي هو ${todayStr} - ${dayName})\n\n${transcript}`;

return [{
  json: {
    message: {
      chat: { id: chatId },
      text: combinedText
    }
  }
}];

