const msg = ($json.messages && $json.messages[0]) || null;
const contact = ($json.contacts && $json.contacts[0]) || null;

if (!msg) {
  // Not an incoming message event (e.g. a status update webhook) - stop this branch.
  return [];
}

const chatId = msg.from;
const type = msg.type;

let text = '';
let photo = null;
let voice = null;
let caption = '';

if (type === 'text') {
  text = (msg.text && msg.text.body) || '';
} else if (type === 'image') {
  photo = [{ file_id: msg.image && msg.image.id }];
  caption = (msg.image && msg.image.caption) || '';
} else if (type === 'audio') {
  voice = { file_id: msg.audio && msg.audio.id };
}

return [{
  json: {
    message: {
      chat: { id: chatId },
      text: text,
      photo: photo,
      voice: voice,
      caption: caption,
      from: { first_name: (contact && contact.profile && contact.profile.name) || '' }
    }
  }
}];
